-- Arbeitsrecht Berufsbildung > Wirtschaftliche Zusammenhänge > Wirtschaftliche Trends > Nachhaltigkeitstrends
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Beeinflussen Nachhaltigkeitstrends die Geschäftsstrategien eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Nachhaltigkeit wird zunehmend strategisch wichtig"}, {"text": "Nein", "correct": false, "because": "Nachhaltigkeit ist ein Trend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Nachhaltigkeitstrends einem IT-Betrieb Wettbewerbsvorteile verschaffen?', 2, '[{"text": "Ja", "correct": true, "because": "Nachhaltigkeit hebt sich im Wettbewerb ab"}, {"text": "Nein", "correct": false, "because": "Vorteile durch Nachhaltigkeit möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Erhöhen Nachhaltigkeitstrends die Kosten für einen IT-Betrieb?', 2, '[{"text": "Ja", "correct": true, "because": "Investitionen in Nachhaltigkeit können Kosten steigern"}, {"text": "Nein", "correct": false, "because": "Kosten können kurzfristig steigen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Nutzung erneuerbarer Energien ein Teil der Nachhaltigkeitstrends in der IT-Branche?', 2, '[{"text": "Ja", "correct": true, "because": "Erneuerbare Energien fördern Nachhaltigkeit"}, {"text": "Nein", "correct": false, "because": "Teil des Trends"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch Nachhaltigkeitstrends langfristig Kosten senken?', 2, '[{"text": "Ja", "correct": true, "because": "Energieeffizienz und Ressourcenschonung sparen Kosten"}, {"text": "Nein", "correct": false, "because": "Langfristige Einsparungen möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein zentraler Aspekt von Nachhaltigkeitstrends für einen IT-Betrieb?', 2, '[{"text": "Ressourcenschonung", "correct": true, "because": "Nachhaltigkeit zielt auf Ressourcennutzung"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation wird gefördert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Nachhaltigkeitstrend ist für die IT-Branche besonders relevant?', 3, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Energieverbrauch"}, {"text": "Höhere Materialkosten", "correct": false, "because": "Kein Trendvorteil"}, {"text": "Weniger Digitalisierung", "correct": false, "because": "Digitalisierung bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb aus Nachhaltigkeitstrends?', 3, '[{"text": "Verbessertes Image", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}, {"text": "Geringere Produktqualität", "correct": false, "because": "Qualität bleibt gleich oder steigt"}, {"text": "Höhere Steuerlast", "correct": false, "because": "Steuern unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil von Nachhaltigkeitstrends für einen IT-Betrieb?', 2, '[{"text": "Kurzfristige Investitionskosten", "correct": true, "because": "Nachhaltigkeit erfordert Anfangsinvestitionen"}, {"text": "Weniger Kunden", "correct": false, "because": "Kunden bevorzugen Nachhaltigkeit"}, {"text": "Einfachere Prozesse", "correct": false, "because": "Prozesse können komplexer werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource wird durch Nachhaltigkeitstrends in der IT-Branche geschont?', 3, '[{"text": "Energie", "correct": true, "because": "Energieeffizienz ist zentral"}, {"text": "Produktionszeit", "correct": false, "because": "Zeit nicht primär"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Kein direkter Zusammenhang"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Nachhaltigkeitstrends einem IT-Betrieb?', 4, '[{"text": "Kostensenkung langfristig", "correct": true, "because": "Energieeffizienz spart Kosten"}, {"text": "Verbessertes Unternehmensimage", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}, {"text": "Weniger Innovation", "correct": false, "because": "Innovation wird gefördert"}, {"text": "Wettbewerbsvorteile", "correct": true, "because": "Nachhaltigkeit hebt ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile können Nachhaltigkeitstrends für einen IT-Betrieb mit sich bringen?', 3, '[{"text": "Kurzfristige Investitionskosten", "correct": true, "because": "Anfangsinvestitionen nötig"}, {"text": "Komplexere Prozesse", "correct": true, "because": "Nachhaltigkeit kann Prozesse verändern"}, {"text": "Geringere Qualität", "correct": false, "because": "Qualität bleibt oder steigt"}, {"text": "Erhöhte regulatorische Anforderungen", "correct": true, "because": "Gesetze können strenger werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachhaltigkeitstrends sind für die IT-Branche relevant?', 4, '[{"text": "Energieeffiziente Hardware", "correct": true, "because": "Reduziert Energieverbrauch"}, {"text": "Recycling von IT-Komponenten", "correct": true, "because": "Fördert Ressourcenschonung"}, {"text": "Höhere Produktionskosten", "correct": false, "because": "Kein direkter Trend"}, {"text": "Cloud Computing mit grüner Energie", "correct": true, "because": "Nachhaltige Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern Nachhaltigkeitstrends in der IT-Branche?', 3, '[{"text": "Kundennachfrage nach Nachhaltigkeit", "correct": true, "because": "Kunden bevorzugen grüne Lösungen"}, {"text": "Technologische Innovationen", "correct": true, "because": "Fördert nachhaltige Lösungen"}, {"text": "Weniger Digitalisierung", "correct": false, "because": "Digitalisierung bleibt"}, {"text": "Gesetzliche Vorgaben", "correct": true, "because": "Regulierungen treiben Trends"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet Nachhaltigkeitstrends von anderen Wirtschaftstrends für einen IT-Betrieb?', 3, '[{"text": "Fokus auf Ressourcenschonung", "correct": true, "because": "Nachhaltigkeit zielt auf Umwelt"}, {"text": "Langfristige Kostenorientierung", "correct": true, "because": "Nachhaltigkeit spart langfristig"}, {"text": "Geringere Bedeutung", "correct": false, "because": "Nachhaltigkeit ist bedeutend"}, {"text": "Einfluss auf Unternehmensimage", "correct": true, "because": "Nachhaltigkeit stärkt Reputation"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Nachhaltigkeitstrends fördern die Energieeffizienz in der IT-Branche. b) Nachhaltigkeitstrends reduzieren kurzfristig die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Energieeffizienz ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nachhaltigkeitstrends bieten Wettbewerbsvorteile für einen IT-Betrieb. b) Nachhaltigkeitstrends erhöhen langfristig die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wettbewerbsvorteile ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nachhaltigkeitstrends verbessern das Image eines IT-Betriebs. b) Nachhaltigkeitstrends sind für kleine IT-Betriebe irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Image ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Nachhaltigkeitstrends fördern Recycling in der IT-Branche. b) Nachhaltigkeitstrends führen immer zu geringeren Investitionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Recycling ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nachhaltigkeitstrends können durch Kundennachfrage angetrieben werden. b) Nachhaltigkeitstrends haben keinen Einfluss auf die IT-Branche.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kundennachfrage ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

